<?php if($auth->can('dispositivi','esecuzione')): ?><section class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Registra un controllo</h2><p class="text-secondary">Le coordinate vengono raccolte solo se premi il pulsante qui sotto; non viene effettuato tracciamento continuo.</p><form method="post" action="/app/dispositivi/<?= (int)$dispositivo['id'] ?>/controlli" class="row g-3" data-device-check><?= $csrf->field() ?><input type="hidden" name="latitudine"><input type="hidden" name="longitudine"><div class="col-md-6"><label class="form-label">Esito del controllo<select class="form-select" name="esito" required><option value="">Seleziona…</option><?php foreach(['regolare'=>'Regolare','attivita_rilevata'=>'Attività infestante rilevata','esca_consumata'=>'Esca consumata','anomalia'=>'Anomalia','non_accessibile'=>'Non accessibile'] as $key=>$label): ?><option value="<?= e($key) ?>"><?= e($label) ?></option><?php endforeach ?></select></label></div><div class="col-md-6"><label class="form-label">Consumo<input class="form-control" name="consumo" placeholder="Nessuno, lieve, medio, elevato"></label></div><div class="col-md-6"><label class="form-label">Tipo esca sostituita<input class="form-control" name="tipo_esca"></label></div><div class="col-md-6"><label class="form-label">Quantità sostituita<input class="form-control" type="number" min="0" step="0.001" name="quantita_esca"></label></div><div class="col-12"><label class="form-label">Attività svolta<textarea class="form-control" name="attivita" rows="2" placeholder="Es. controllo, pulizia, sostituzione esca"></textarea></label></div><div class="col-12"><label class="form-label">Anomalie<input class="form-control" name="anomalia"></label></div><div class="col-12"><label class="form-label">Note<textarea class="form-control" name="note" rows="2"></textarea></label></div><div class="col-12 d-flex gap-2"><button class="btn btn-primary">Salva controllo</button><button class="btn btn-outline-secondary" type="button" data-use-location>Allega posizione attuale (facoltativo)</button></div><div class="small text-secondary" data-location-status aria-live="polite"></div></form></div></section><?php endif ?></div></div>
<section class="mt-4"><h2 class="h4">Storico dei controlli</h2><?php if(!$controlli): ?><div class="card border-0 shadow-sm"><div class="empty-state">Nessun controllo registrato finora.</div></div><?php else: ?><div class="table-wrap"><table class="table table-hover align-middle"><thead><tr><th>Data</th><th>Operatore</th><th>Esito</th><th>Attività</th><th>Note</th></tr></thead><tbody><?php foreach($controlli as $c): ?><tr><td><?= e(date('d/m/Y H:i',strtotime($c['controllato_il']))) ?></td><td><?= e($c['operatore']) ?></td><td><?= e(ucfirst(str_replace('_',' ',$c['esito']))) ?></td><td><?= e($c['attivita']?:'—') ?></td><td><?= e($c['anomalia']?:$c['note']?:'—') ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
